// The Italian of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/it/index.ts).
export const whatsNew: Record<string, string> = {
  "What's new": 'Novità',
  'What each version changed': 'Cosa è cambiato in ogni versione',
  'What each version of Erevos changed, the newest first.': 'Cosa è cambiato in ogni versione di Erevos, dalla più recente.',
  'Not out yet': 'Non ancora uscita',
  'This version': 'Questa versione',
  'For you': 'Per te',
  'Under the hood': 'Sotto il cofano',
  // Not out yet.
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**I link si aprono su Sailfish OS**: **Accedi con LPHL**, una pagina di donazione o un link in una chat non aprivano nulla. Ora li apre Sailfish OS: una pagina web nel browser, un numero nel telefono o nei messaggi, un indirizzo nella posta.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix, e foto e file nelle chat XMPP e Nostr, su Sailfish OS**: lì Erevos non raggiungeva i loro server via HTTPS, quindi Matrix non poteva accedere, foto e file non arrivavano né partivano e i link non mostravano l'anteprima. Ora funzionano come su un computer.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Una chiamata telefonica mostra la sua schermata**: con Erevos come app Telefono, una chiamata in arrivo poteva squillare con lo schermo nero, senza poter rispondere, quando erano disattivate le notifiche a schermo intero di Android per Erevos, le notifiche di Erevos o le sue notifiche delle chiamate in arrivo. Ora la schermata di chiamata compare da sola, anche sulla schermata di blocco, e accende lo schermo. Una chiamata che «Non disturbare» trattiene arriva ancora in silenzio, a schermo spento. Vedi [Telefono](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**La calcolatrice mostra un risultato lungo dall'inizio**: in verticale, un risultato con molti decimali nascondeva le prime cifre, visibili solo con il telefono in orizzontale. Ora un numero lungo si rimpicciolisce per starci, con le prime cifre sempre in vista.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Scegli il destinatario di un nuovo SMS tra i contatti**: **Nuovo SMS** ha un pulsante **Contatti** che apre i tuoi contatti con una ricerca, e scrivendo un nome o un numero vengono suggeriti i contatti che corrispondono. Un contatto con più numeri mostra una riga per ciascuno, e in un MMS di gruppo ogni contatto scelto si aggiunge. Con solo gli SMS aperti compaiono solo i contatti del telefono. Vedi [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Altro per un numero nel Telefono**: sulla tastiera, **⋯** accanto a un numero digitato offre **Aggiungi ai contatti**, **Aggiungi a un contatto esistente**, **Invia un SMS** e **Copia il numero**. **Recenti** e **Preferiti** offrono **Copia il numero** e **Apri il contatto**; i **Preferiti** anche **Invia un SMS**, e i **Recenti** aggiungono un numero sconosciuto a un contatto esistente. Con Erevos bloccato, il Telefono continua solo a chiamare. Vedi [Telefono](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Una breve vibrazione al tocco**: i tasti della tastiera, **Chiama**, **Termina**, Invia, l’Invio della tastiera, gli interruttori e i menu che si aprono danno una breve vibrazione. In **Impostazioni** → **Aspetto** → **Vibrazione al tocco** la spegni. Vedi [Aspetto](#appearance).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Un numero su ogni icona, su Huawei e Honor**: i loro launcher ora mostrano un numero su ciascuna icona di Erevos a parte, con **Numero sull’icona** attivo: su quella di Erevos i messaggi, su quella degli SMS gli SMS non letti, su quella del Telefono le chiamate perse, su quella dei Contatti un compleanno di oggi. La maggior parte degli altri launcher, come quelli dei Pixel e di GrapheneOS, quello di Samsung e Kvaesitso, dà il punto o il numero di una notifica a tutte le icone di un’app allo stesso modo, e lì Erevos non può cambiarlo. Vedi [Aspetto](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Scegli le parti di Erevos che usi**: le chat di Erevos, il Telefono, gli SMS e le chat con app Nostr, Matrix e XMPP ora sono moduli, uno qualsiasi può essere attivo, anche quello di Erevos, almeno uno. Uno disattivato non si avvia e non compare da nessuna parte, e le icone del Telefono e degli SMS escono dalle app del telefono: Erevos è più leggero, si apre più in fretta e consuma meno batteria. Di esso non si cancella nulla: torna tutto quando viene riattivato. Il primissimo avvio di Erevos lo configura come fa un installer, la lingua, i moduli e ciò che Android deve consentire per loro; un modulo attivato più tardi chiede di nuovo le sue autorizzazioni. Dopo questo aggiornamento ogni modulo resta attivo finché non lo cambi in **Impostazioni** → **Generali** → **Moduli**. Vedi [Moduli](#modules).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Post pubblici nella scheda Nostr**: nella schermata principale, la scheda Nostr mostra per primi i **Post**, i post pubblici delle persone che la tua chiave Nostr segue e quello che hanno condiviso di nuovo, dal più recente, come in Amethyst o in un canale Telegram, con le **Chat** a un tocco. I meno recenti arrivano quando scorri fino in fondo, i più recenti quando tiri giù la lista; tocca chi ha scritto un post per i suoi post o per scrivergli. In sola lettura, cercati tramite Tor come dice lo spazio e non conservati, e non vengono aperte immagini né link. Vedi [Chat con altre app Nostr](#nostr-chats).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**Erevos non si ferma più quando sono aperti solo gli SMS o i contatti**: da lì, la chat di un contatto, un SMS, un'altra icona o una schermata che chiede di nuovo la password potevano far dire a Erevos che non si era potuto aprire (Maximum call stack size exceeded). Ora la password apre tutto Erevos e poi quella schermata. E quando Erevos non si può aprire, **Riprova** lo riavvia. Vedi [Blocco con password](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Ogni icona apre ciò che indica**: dopo che Erevos era stato aperto dall’icona SMS o dalle app recenti, un’altra icona, il widget o una notifica potevano a volte mostrare invece gli SMS. Ora ognuno apre ciò che indica. Quando sono aperti solo gli SMS o i contatti, un’altra icona chiede la password come quando Erevos è bloccato e poi apre la propria parte: l’icona Contatti solo i contatti, l’icona stessa di Erevos tutto Erevos. E Indietro nella prima schermata di Erevos ora lo mette in secondo piano, come Home, qualunque cosa lo abbia aperto. Vedi [Blocco con password](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Solo i Contatti**: con Erevos bloccato, l’icona Contatti, il pulsante Contatti del widget e la notifica di un compleanno chiedono la password e poi aprono solo i contatti. Una chat, un SMS, le Impostazioni e il lucchetto arancione **Sblocca tutto** la chiedono di nuovo e poi aprono tutto Erevos. Vedi [Blocco con password](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Vecchi messaggi privati nelle chat Nostr**: Erevos legge anche i messaggi privati mandati alla vecchia maniera (NIP-04), che Damus, Primal e molte app ancora mandano e tengono: passati e nuovi, nelle stesse chat. I relay vedono chi ha scritto un messaggio così a chi; Erevos stesso manda ancora solo alla maniera di NIP-17. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Post pubblici nelle chat Nostr**: in una chat con una persona, **Post pubblici** mostra quello che pubblica per tutti, dal più recente, in sola lettura. Viene cercato tramite Tor come dice lo spazio e non viene conservato, e non vengono aperte immagini né link. Vedi [Chat con altre app Nostr](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Licenza**: Impostazioni → Generali → Licenza dice con quale licenza Erevos è software libero, AGPL-3.0-or-later, le sue tre condizioni aggiuntive, che viene senza alcuna garanzia, e chi l’ha fatto. Vedi [Licenza](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Contatto**: Impostazioni → Generali → Contatto aggiunge l’autore di Erevos come contatto, per scrivergli nello stesso Erevos, con crittografia end-to-end, senza numero di telefono né email. Vedi [Che cos’è Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Un nuovo set di adesivi, Angry Eyes**: 24 volti di grandi occhi gialli su un disco nero, disegnati dall’autore di Erevos, ciascuno con i movimenti che gli ha dato.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**La calcolatrice si apre di nuovo**: nella 4.0.0-rc.6 si chiudeva appena la toccavi.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Le persone che segui su Nostr sono cercate su più relay**: **Mostra le persone che segui** interroga anche relay che raccolgono le liste dei seguiti e più dei relay dove scrive la tua chiave, e li aspetta più a lungo; quando non trova nessuno, dice perché e come ha risposto ogni relay. Vedi [Chat con altre app Nostr](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Password di panico**: con il blocco con password attivo, **Imposta la password di panico** in «Pulsante di panico» imposta una password tutta sua che, scritta sulla schermata di blocco, cancella Erevos come fa **Cancella tutto ora**, mentre la schermata mostra **Password errata**. Niente mostra se ce n’è una impostata. Vedi [Pulsante di panico](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Calcolatrice al posto di Erevos**: su Android, in «Icone del launcher», una calcolatrice che funziona può prendere il posto dell’icona di Erevos; il tuo codice, poi **=**, apre Erevos, che chiede la sua password come sempre. Vedi [Aspetto](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Chat con me stesso anche sui tuoi dispositivi collegati**: note, foto, file, messaggi vocali e promemoria scritti su un dispositivo vanno agli altri, come un promemoria cambiato o visto e una nota eliminata. Quelli di prima vanno una volta, nei due sensi. Vedi [Dispositivi collegati](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Avvia all’accensione del telefono**: su Android, in «In background», Erevos può avviarsi da solo dopo l’accensione del telefono, così gli spazi impostati per dire che è arrivato un messaggio mentre sono chiusi dicono già «New message», mai quale spazio o cosa. Disattivato se non lo scegli. Vedi [Chat tramite un relay](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Spostare l’orologio non conclude più l’attesa dopo password sbagliate**: segue il tempo proprio del telefono da quando si è avviato, che nessuno può impostare; dopo un riavvio ricomincia dall’inizio. Vedi [Blocco con password](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Le persone che segui su Nostr, trovate dove le tiene la tua altra app**: con una chiave portata da un’altra app Nostr, **Mostra le persone che segui** cerca anche sui relay dove scrive la tua chiave, e lo dice quando nessun relay ha risposto. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Il tuo nome Nostr tiene il resto del tuo profilo**: salvare **Il tuo nome** cambia solo il nome nel tuo profilo; una foto o delle parole che un’altra app della tua chiave ci ha messo restano. Prima potevano essere cancellate. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**Le schermate scendono quando non c’è una tastiera aperta, in ogni caso**: l’elenco e i pulsanti della schermata iniziale, o una chat, potevano ancora restare in alto come se una tastiera fosse aperta, dopo che se n’era andata. Ora Erevos chiede ad Android stesso se una tastiera è mostrata, e senza tastiera scendono entro un secondo.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Nuova chat apre prima le chat nascoste**: tieni premuto **Nuova chat** per un attimo, non più un secondo intero, e si apre il campo per un PIN delle chat nascoste; su Android il telefono vibra una volta quando si apre. Vedi [Chat nascoste](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Le persone che segui su Nostr**: nelle Chat Nostr, sotto Nuova chat, **Mostra le persone che segui** elenca le persone che la tua chiave Nostr segue, con i loro nomi; tocca una persona per scriverle. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Chi fa Erevos, e la sua licenza**: Informazioni su Erevos ora dice chi lo fa, e ogni file del codice sorgente dice di chi è e con quale licenza; la licenza AGPL-3.0 ha tre condizioni aggiuntive (mantenere il nome dell’autore, segnare una versione modificata come modificata, darle un altro nome). Vedi [Che cos’è Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Numeri sui chip della schermata principale**: ogni chip sopra le chat (Tutti, SMS, Erevos, Matrix, XMPP, Nostr) mostra quanti messaggi non letti ci sono, con un piccolo numero dopo il suo nome; le chat e i gruppi in silenzio non contano. Vedi [Per iniziare](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Foto a schermo intero nelle chat Matrix, XMPP e Nostr**: tocca una foto mostrata in una chat Matrix, XMPP o Nostr per vederla a tutto schermo, con zoom, rotazione con il telefono e Salva, come nella chat con un contatto. Vedi [Matrix](#matrix), [XMPP](#xmpp) e [Chat con altre app Nostr](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Chi ha ricevuto e chi ha letto i tuoi messaggi nei gruppi**: in un gruppo che non è pubblico, i tuoi messaggi mostrano ✓, poi ✓✓ quando sono arrivati al telefono di ogni membro, e ✓✓✓ quando tutti li hanno letti. Tieni premuto uno e scegli **Chi l’ha letto** per vedere chi l’ha letto e quando, al telefono di chi è arrivato e quando, e chi non ha ancora fatto né l’una né l’altra cosa. Un membro con un Erevos più vecchio non dice nulla. Un computer collegato mostra gli stessi segni. Vedi [Chat tramite un relay](#relay) e [Chat di gruppo](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Chi ha letto i tuoi messaggi in Matrix**: i tuoi messaggi in una chat Matrix mostrano ✓ quando il server Matrix li ha presi e ✓✓✓ quando tutti gli altri membri li hanno letti, come le loro app Matrix lo dicono ai loro server; **Chi l’ha letto**, su un messaggio tenuto premuto, elenca chi l’ha letto e quando, e chi no. Matrix non ha un segno per un messaggio arrivato a un telefono, quindi non c’è ✓✓. Vedi [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Messaggi di gruppo silenziosi per i segni**: il messaggio di gruppo che dice che un messaggio è arrivato o è stato letto va solo ai mittenti interessati, e in blocco; dopo 300 di questi messaggi inviati solo ad alcuni membri, il successivo va a tutti, così nessun membro resta indietro nelle chiavi MLS del telefono (accettano un salto di 1000 al massimo). I gruppi lasciati andare quando si chiude il loro spazio non inviano più nulla. Vedi [Chat di gruppo](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Grassetto, corsivo, codice e parole nascoste**: nelle chat e nei gruppi, le parole tra * diventano in grassetto, tra _ in corsivo, tra ~ barrate, tra ` codice, e tra || nascoste dietro una barra grigia finché non le tocchi. Vedi [Chattare tramite un relay](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Foto nascosta**: sotto + in una chat o in un gruppo, una foto che appare sfocata finché non la tocchi. Vedi [Chattare tramite un relay](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Messaggio di sicurezza**: sotto + in una chat, parole per un contatto che il relay invia da solo se non apri Erevos per un periodo da 6 ore a una settimana; ogni volta che lo apri, slittano di nuovo. Vedi [Chattare tramite un relay](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Nomina un membro in un gruppo con @**: scrivi @ e scegli un membro; viene avvisato del messaggio anche se ha silenziato il gruppo. Vedi [Chat di gruppo](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Rispondi, modifica, reagisci ed elimina nelle chat XMPP**: tieni premuto un messaggio in una chat o in un gruppo XMPP per rispondere, cambiare le tue parole, eliminarlo per tutti o reagire con un’emoji, come fanno Conversations, Dino, Gajim, Monal e Kaidan; e **sta scrivendo…** compare mentre l’altra persona scrive. Vedi [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Vedi chi sta scrivendo in una chat Matrix**: **sta scrivendo…** compare sotto una chat Matrix mentre qualcuno ci scrive, come dice il server Matrix. Di te si vede solo se attivi **Dire quando scrivo** nella schermata Matrix o XMPP: spento all’inizio, perché passa dal server senza cifratura. Vedi [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Blocca qualcuno su XMPP**: Blocca, in fondo a una chat XMPP, tiene messaggi, chiamate e richieste di quella persona lontani da ogni app del tuo account XMPP; Sblocca la fa passare di nuovo. Vedi [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Messaggi vocali nelle chat XMPP**: tieni premuto il microfono sotto il campo del messaggio di una chat XMPP per registrare, e rilascia per inviare; parte cifrato come la chat, come lo invia Conversations. Vedi [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Gruppi Matrix da Erevos**: Nuovo gruppo, nella schermata di Matrix, crea un gruppo cifrato con un nome e le persone che inviti; Entra in un gruppo entra in uno con il suo indirizzo; Invita, in un gruppo, fa entrare qualcun altro; scrivere @ in un gruppo nomina un membro, che viene avvisato. Vedi [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**Il pulsante di panico su un computer e su Sailfish OS**: Impostazioni → Privacy e sicurezza → Pulsante di panico ora cancella Erevos anche lì, con i suoi backup automatici se lo scegli; su un computer poi riparte come nuovo. Vedi [Pulsante di panico](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Ogni chat si apre sul suo ultimo messaggio**: le chat con i contatti, i gruppi e gli SMS, e le chat Matrix, XMPP e Nostr si aprono tutte sull’ultimo messaggio con la barra dei messaggi sotto, e hanno frecce rotonde verso l’inizio, verso dove avevi lasciato (il primo messaggio che era nuovo all’apertura) e verso la fine. Vedi [Per iniziare](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**Il pulsante di panico dice quando ha rifiutato**: quando la tua app di panico ha chiesto di cancellare Erevos con l’interruttore spento, o firmata con un’altra chiave, la schermata del pulsante di panico ora lo dice, con l’ora. Un’app che passa a una nuova chiave nel modo che Android permette resta fidata; altrimenti puoi fidarti di nuovo così com’è ora. Vedi [Pulsante di panico](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**I chip della schermata principale restano su una riga**: con in più un chip Nostr, Matrix o XMPP, **Nomi** andava su una riga a parte e i chip si spostavano. Ora restano su una sola riga che scorre di lato, e quello scelto è sempre in vista.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**Le schermate scendono quando la tastiera se ne va**: tornando da un’altra app con la tastiera aperta, i pulsanti della schermata iniziale (o il campo di una chat) potevano restare in alto, dov’era la tastiera, finché non si riapriva una tastiera. Ora scendono entro un secondo.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Guarda ciò che scrivi in una password o un PIN**: ogni campo per una password, un PIN o un token ha un occhio in fondo: toccalo per vedere ciò che scrivi, e di nuovo per nasconderlo. La volta dopo è di nuovo nascosto. Vedi [Blocco con password](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Una chat letta mentre si apre resta letta**: i messaggi letti mentre la loro chat si stava ancora aprendo, mentre Erevos finiva di guardare sul relay, risultavano non letti nella schermata principale appena tornavi indietro. Ora sono segnati come letti appena si vedono.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Link per un sito web**: in Nuova chat → Il tuo link di contatto, un link da mettere su una pagina web, come la tua pagina dei contatti. Apre una pagina che offre Erevos a chi non ce l’ha ancora, poi ti aggiunge; ciò che invia arriva come richiesta di messaggio. Vedi [Chat tramite un relay](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Il download di un aggiornamento che si blocca viene ritentato**: quando la connessione non porta nulla per un po’, Erevos riparte da solo con il download, tre volte in tutto, e poi lo dice con parole sue. Vedi [Aggiornamenti](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**I pezzi delle foto tramite Nostr restano con le loro chat**: mentre una foto che arriva tramite Nostr aspetta il resto dei suoi pezzi, questi sono ora tenuti cifrati con lo spazio o le chat nascoste per cui sono arrivati, non più a parte, dove si potevano contare, così niente fuori dalla password di chat nascoste dice che una foto sta arrivando a loro. I pezzi tenuti prima vanno alle prime chat di cui sono la foto, o se ne vanno dopo quattro giorni. Vedi [Tramite Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**SMS crittografati quando nient’altro funziona, se lo scegli**: su Android, quando relay, Nostr, i telefoni vicini e LoRa falliscono tutti, un testo a un contatto Erevos con numero collegato può andare via SMS, crittografato end-to-end e nascosto alla sua app per gli SMS. Disattivato finché non lo attivi, per tutti questi contatti in Impostazioni → Telefono e SMS → SMS, o per uno nei Dettagli di una chat. Costa SMS (3 per un testo breve, fino a 10 per uno più lungo), e l’operatore vede chi ha scritto a chi, e quando. Entrambi i telefoni hanno bisogno di Erevos come app per gli SMS. Vedi [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Rispondere a una chiamata nascosta con Rispondi**: sulla schermata «Chiamata in arrivo» senza nome che porta una chiamata alle tue chat nascoste, **Rispondi** ora chiede il PIN, come il piccolo segno, e il PIN giusto risponde alla chiamata; prima non poteva collegare, e solo il piccolo segno poteva. Vedi [Chat nascoste](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**Gli SMS di spam arrivano in silenzio**: su Android, un SMS che le parole proprie del filtro antispam colgono, un link con parole che cercano di ingannare da un numero che non è un contatto e a cui non hai mai risposto, va ancora in Spam ma non mostra più una notifica né suona. Lo spam per le tue parole e regole ne mostra ancora una, perché restano cifrate nello spazio; con il Filtro antispam spento, ogni SMS la mostra. Vedi [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Le novità in due parti**: ogni versione dice prima cosa cambia per te, poi cosa è cambiato sotto il cofano: correzioni, velocità, batteria e sicurezza all’interno. Vedi [Aggiornamenti](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Gli SMS di un contatto non restano più contati come nuovi**: aprire la sua chat li legge tutti, anche i precedenti, non solo quelli visibili.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Un messaggio non resta più in attesa quando Tor non raggiunge il relay**: con Tor per i messaggi, parte subito in diretta, come dicono le impostazioni di Tor. Vedi [Tramite Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Gli avvisi in background non si fermano più dopo un cambio di rete**: quando la connessione di un’attesa al relay moriva per strada (da Wi-Fi a dati mobili, riavvio del relay), Erevos prendeva il relay per uno vecchio, che non sa aspettare, per tutta l’esecuzione: i messaggi dei contatti arrivavano fino a dieci minuti dopo, e le chat nascoste, gli spazi chiusi e gli squilli nascosti non dicevano nulla fino al riavvio di Erevos. Vedi [Chat tramite un relay](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Una chiamata chiusa subito non squilla più**: quando la chiusura arrivava nello stesso sguardo della chiamata, il telefono squillava 45 secondi per una chiamata in cui non c’era nessuno; lo stesso per una chiamata di gruppo che chi l’ha avviata ha lasciato subito. Vedi [Chat tramite un relay](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Una chiamata nascosta squilla una volta**: un posto con Ricevere da chiuse e una coda di squillo squillava due volte per una chiamata, e una chiamata presa mentre le chat nascoste erano aperte squillava di nuovo alla loro chiusura. Vedi [Chat nascoste](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**Il link di contatto di un membro non dice più Nuovo messaggio**: la risposta a una richiesta da un gruppo aggiunge solo il contatto, senza avviso. Vedi [Chat di gruppo](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**L’avviso di compleanno e la chiamata in arrivo del telefono non si sostituiscono più**: avevano lo stesso numero di avviso. Vedi [Contatti](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Uno spazio chiuso avvisa anche dei messaggi dei suoi contatti**: poiché ogni contatto scrive in una coda tutta sua, uno spazio che avvisa che è arrivato un messaggio mentre ne è aperto un altro avvisava solo dei messaggi dei gruppi e dei primi messaggi dei nuovi contatti. Ora chiede anche delle code dei suoi contatti, fino a 64. Vedi [Chat tramite un relay](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**La guida è in tutte le lingue dell’app**: appare in quella che hai scelto e chiama i pulsanti come li mostra l’app. Vedi [Lingua](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Posizione trova dove ti trovi, anche al chiuso**: il telefono cerca via satellite e con la sua rete insieme, un foglio dice che sta cercando, e se non trova niente dice perché, con Riprova. Vedi [Chat tramite un relay](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**L\'icona della web app conta i non letti**: su un iPhone, con le notifiche attive per lo spazio, l\'icona di Erevos nella schermata Home mostra quanti messaggi non sono letti, mai quelli di una chat nascosta, a meno che tu non lo spenga in Impostazioni → Notifiche → Numero sull\'icona. Vedi [Su un iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Notifiche per ogni chat**: su Android, metti in silenzio una chat o un gruppo per 8 ore, una settimana o sempre, e dai ai suoi messaggi e alle sue chiamate un suono proprio, o nessuno. Vedi [Chat tramite un relay](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Una chat bloccata con un PIN suo resta bloccata**: quando l’Erevos del contatto iniziava una nuova conversazione, come fa circa una volta al mese, la chat perdeva il suo PIN, e un gruppo pubblico in cui sei rientrato perdeva il suo. Vedi [Chat nascoste](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**L'icona di Erevos tiene il numero dei messaggi non letti, su Android**: uscendo da Erevos con messaggi non letti, una notifica senza suono tiene quanti sono finché non li leggi, e il launcher la mostra sull'icona, come numero o punto. Impostazioni → Notifiche → Numero sull'icona lo disattiva. Vedi [Chat tramite un relay](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    "**Le notifiche della web app, più affidabili**: nessun «Nuovo messaggio» sopra Erevos mentre è aperto, e un push trattenuto mentre il telefono era offline non conta più i messaggi che hai già letto (entrambi con il tuo relay aggiornato), ogni avviso fa un suono in Chrome, Firefox ed Edge, tornano da sole quando il browser cambia il suo indirizzo push, e «Notifiche ad app chiusa» dice quando il browser le blocca o quando al tuo relay non è ancora stato detto che sono disattivate. Vedi [Su un iPhone](#iphone).",
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**Le chiamate squillano nella web app, sul computer e su Sailfish OS**: una chiamata che arriva mentre Erevos è aperto ora squilla, dove prima si vedeva solo la sua schermata, e vibra dove il telefono può. Su un iPhone squilla dopo che hai toccato Erevos, e non in silenzioso. Vedi [Su un iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**Erevos sul computer continua a funzionare con la finestra chiusa**: nell’area di notifica (su un Mac, nel Dock) continua a ricevere, una chiamata squilla e riporta la finestra, e una notifica dice quanti messaggi non sono letti, mai chi né cosa. Si disattiva in Impostazioni → Notifiche → In background. Vedi [Su un computer](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**Erevos su Sailfish OS avvisa di messaggi e chiamate mentre è chiuso**: mentre non si vede o è chiuso, un piccolo aiutante aspetta sul relay per lo spazio aperto, una notifica dice quanti messaggi sono arrivati, mai da chi né cosa, e una chiamata suona con la suoneria del telefono. Vedi [Su Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    "**I push del relay alla web app, più solidi**: un push che il servizio push non ha potuto accettare in quel momento viene inviato di nuovo, una chiamata passa prima dei messaggi che aspettano il loro turno, e chi gestisce il relay può consentire un altro servizio push. Il tuo relay deve essere aggiornato per questo.",
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    '**Autorizzazioni controlla ogni notifica che Erevos usa**: su Android, la notifica dei messaggi senza suono o con il suono proprio di una chat, e quella dei promemoria, se disattivate, ora appaiono lì, con un pulsante per ciascuna. Vedi [Chat tramite un relay](#relay).',
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**Le chat nascoste dicono di che cosa hanno bisogno i loro interruttori**: Avvisa quando arriva un messaggio e Fai squillare le chiamate quando sono chiuse lo dicono quando Impostazioni → Notifiche → In background non permette loro di fare nulla. Vedi [Chat nascoste](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    '**Parole più fedeli sulle notifiche**: le Impostazioni e la guida riportano le parole stesse delle notifiche e dicono di che cosa ha bisogno ciascuna. Vedi [Chat tramite un relay](#relay).',
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    '**Le chiamate squillano come devono**: con Non disturbare solo quando la loro notifica può passare, anche con l’orologio di un telefono sballato una volta aggiornato il relay, e fino alla fine su Android 7 e 8; a una seconda chiamata viene detto occupato, e uno squillo si ferma solo per la sua chiamata. Vedi [Chat tramite un relay](#relay).',
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Chiamate nascoste**: una rifiutata non lascia più Erevos sopra la schermata di blocco, una che arriva mentre è visibile la schermata della password appare sopra di essa, e nessuna squilla due volte. Vedi [Chat nascoste](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Le notifiche tornano subito dopo un cambio di rete**, e la ricezione riparte appena Erevos è visibile quando Android l’aveva rifiutata. Vedi [Chat tramite un relay](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    '**Le notifiche delle chat nascoste annunciano ogni messaggio una volta**: quello che è arrivato dall’ultima volta che un posto ha guardato viene annunciato quando si chiude, una chiamata che ha squillato non viene annunciata di nuovo come messaggio, e un posto la cui coda è stata persa dal relay tiene attivo il suo interruttore. Vedi [Chat nascoste](#hidden).',
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**Le chat nascoste si chiudono mentre Erevos è in background**, dopo 30 secondi, così una chiamata per loro nel frattempo squilla con il loro PIN per rispondere. Vedi [Chat nascoste](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Un messaggio vocale conta una volta**, sulla sua ultima parte, anche quando viene inviato di nuovo per intero.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**Il numero sull’icona conta solo quello che c’è ancora**: un messaggio eliminato per tutti, o letto su un computer collegato, non conta più. Vedi [Chat tramite un relay](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**I messaggi programmati** avvisano di sé solo mentre il loro spazio è aperto, senza suono se inviati così.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS**: uno per la chat sullo schermo suona solo lì, vengono segnati come letti solo mentre la loro schermata è visibile, e Android chiama le loro notifiche SMS. Vedi [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    '**Promemoria**: uno visto nella Chat con me stesso se ne va dalla notifica, quelli di un posto nascosto se ne vanno con un nuovo PIN, e i compleanni arrivano alle 9:00. Vedi [Per iniziare](#start).',
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**Nostr legge appena Tor è pronto.** Vedi [Tramite Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    '**Le notifiche di Erevos mostrano il suo simbolo** nella barra di stato.',
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Le notifiche vengono chieste anche con la ricezione disattivata**, quando Avvisa dei nuovi messaggi è attivo.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**Le foto si aprono a tutto schermo**: tocca una foto per vederla da bordo a bordo, ingrandisci con due dita o un doppio tocco, e tocca di nuovo per nascondere o mostrare ciò che ha intorno; le foto grandi si aprono come quelle piccole. Erevos ruota anche con il telefono finché la sua Rotazione automatica è attiva, e una foto mostrata da sola anche quando è disattivata. Vedi [Chat tramite un relay](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Account Matrix in Erevos**: fai accedere uno spazio a Matrix e chatta con persone che usano Element o un’altra app Matrix, con cifratura end-to-end, in Impostazioni → Relay e reti → Matrix. Queste chat non sono anonime, e lo dicono: il server Matrix vede chi parla con chi. Testo, foto e file. Vedi [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**Le chat di ogni rete nella schermata principale**: una volta che hai fatto l’accesso a Matrix, le sue chat sono nell’elenco con le chat Erevos e gli SMS, le più recenti prima, ognuna segnata Matrix, e il chip Matrix mostra solo loro, come SMS ed Erevos. Vedi [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Versioni di prova prima di una versione**: Erevos legge una versione come 4.0.0-rc.1, una versione di prova che viene prima della 4.0.0, quando cerca aggiornamenti, avvisa di una nuova versione e mostra le novità. Vedi [Aggiornamenti](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Verifica i dispositivi Matrix con le emoji**: in una chat con una persona su Matrix, Verifica con le emoji mostra a entrambi sette immagini; se corrispondono, nessuno sta in mezzo, e anche Element vede la verifica. Verifica questo dispositivo con un altro tuo fa sì che il tuo Element si fidi di Erevos. Vedi [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Backup automatici anche sul tuo server**: su Android, ogni backup automatico può andare anche in una cartella su un server che scegli tu, come il tuo Nextcloud, via WebDAV. Disattivato finché non ne aggiungi uno. Il server riceve byte casuali con un nome casuale e non può aprirli; vede comunque il tuo account, il tuo indirizzo e quando. Vedi [Backup](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Chiave di sicurezza e backup delle chiavi Matrix**: inserisci la chiave di sicurezza creata da Element, in Impostazioni → Relay e reti → Matrix, e i messaggi precedenti si aprono, le nuove chiavi vanno nel backup, e gli altri tuoi dispositivi si fidano di Erevos. Un account senza può crearne una lì. Vedi [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix tramite Tor**: su Android, l’account Matrix di uno spazio segue la sua scelta in Impostazioni → Relay e reti → Tor, così il server Matrix non vede più dove sei; la schermata di Matrix dice quando passa da Tor. Vedi [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**Account XMPP in Erevos**: fai accedere uno spazio a XMPP, in Impostazioni → Relay e reti → XMPP, e chatta con persone che usano Conversations, Monal, Gajim, Dino o un’altra app XMPP, cifrato con OMEMO. Queste chat non sono anonime, e lo dicono: il server XMPP vede chi parla con chi. Testo con segni di consegna e di lettura, foto e file, nell’elenco della schermata iniziale sotto un chip XMPP a parte, e tramite Tor su Android come hai scelto. Vedi [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Chiamate vocali e video con persone su XMPP**: i due riquadri in alto in una chat XMPP chiamano la persona, e le sue chiamate squillano sulla stessa schermata di quelle di Erevos, con le app che chiamano come Conversations. La chiamata passa per il tuo relay per le chiamate o quello del server XMPP, così non conosce il tuo indirizzo; la chiave che la prova passa per i server XMPP, che potrebbero mettersi in mezzo. Vedi [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Chiamate vocali e video con persone su Matrix**: su Android, i due riquadri in alto in una chat Matrix chiamano con Element Call, l’app di chiamata di Element ed Element X, che si apre dentro Erevos in una finestra sua, e le loro chiamate squillano qui come quelle di Erevos. Suono e immagine sono cifrati end-to-end e passano per il server multimediale indicato dal tuo server Matrix, mai per Tor. Vedi [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Chiamate vocali e video con persone su Matrix, nella web app e su un computer**: i due riquadri in alto in una chat Matrix chiamano con Element Call anche lì, come su Android, sopra l’app; la freccia indietro della sua finestra la rimpicciolisce in un angolo, così puoi continuare a usare Erevos durante la chiamata. Element Call gira separato da Erevos e non può leggerne nulla. Vedi [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Chat con persone su altre app Nostr**: dai a uno spazio una chiave Nostr tutta sua, in Impostazioni → Relay e reti → Chat Nostr, e chatta con persone che usano Damus, Amethyst, Primal, 0xchat o un’altra app Nostr, a tu per tu o in gruppo, cifrato come chiede NIP-17: i relay vedono a chi è destinato un messaggio, non chi l’ha scritto. Queste chat non sono anonime, e lo dicono: la tua chiave è la stessa per tutti quelli a cui scrivi. Testo, foto, file e reazioni, nella lista della home sotto un pulsante Nostr tutto suo, e tramite Tor su Android come hai scelto. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Avvisi per i messaggi Matrix, XMPP e Nostr**: un messaggio in una chat Matrix, XMPP o Nostr mostra un avviso e conta nel numero sull’icona di Erevos, come nelle chat di Erevos stesso. Su Android, Notifiche, in fondo a una chat così, la silenzia o le dà un suono suo, e una chiamata XMPP o Matrix squilla con la suoneria della sua chat. Vedi [Matrix](#matrix), [XMPP](#xmpp) e [Chat con altre app Nostr](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Uno spazio chiuso avvisa dei messaggi Matrix**: su Android, «Avvisa dei nuovi messaggi» sotto «Mentre questo spazio è chiuso», nella schermata di Matrix, fa dire «Nuovo messaggio» a uno spazio chiuso quando arriva qualcosa su Matrix mentre un altro spazio è aperto, mai cosa, da chi o in quale chat. Spento finché non lo scegli. Il server Matrix avvisa allora il relay dello spazio di ogni messaggio, senza nessuna sua parola: impara l’indirizzo del relay, e il relay quando arrivano messaggi. Vedi [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Fatto con l’open source degli altri**: In Informazioni su Erevos e nella guida compaiono ora i progetti open source su cui è costruito Erevos, con i loro autori e le loro licenze. Vedi [Che cos’è Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Gruppi su XMPP**: in Impostazioni → Relay e reti → XMPP, crea un gruppo privato con i tuoi contatti, cifrato con OMEMO per ogni membro come i gruppi privati di Conversations, oppure entra in un gruppo con il suo indirizzo, e rispondi agli inviti a gruppi. Un gruppo che non è privato, un canale, non è cifrato, e lo dice. I tuoi gruppi seguono le altre app XMPP del tuo account, e un canale avvisa solo dei messaggi che ti nominano. Vedi [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Di più nelle chat Matrix**: tieni premuto un messaggio per reagire, rispondergli, copiarlo e, se è tuo, modificarlo o eliminarlo per tutti. «Carica i messaggi precedenti» porta dentro quelli più vecchi, e il microfono sotto il campo del messaggio invia messaggi vocali che anche Element riproduce. Le reazioni non sono cifrate, come le invia Element. Vedi [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**Il video aggiunto a una chiamata XMPP**: in una chiamata vocale con qualcuno su XMPP, ognuno di voi può attivare il video con «Aggiungi video»; all’altra persona si chiede prima e può dire «Non ora». Funziona con le app che aggiungono il video a una chiamata come Conversations. Vedi [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Messaggi vocali e risposte nelle chat Nostr**: tieni premuto il microfono sotto il campo del messaggio per inviare un messaggio vocale, che si riproduce con «Riproduci»; tieni premuto un messaggio per rispondergli, e la risposta mostra il messaggio a cui risponde, qui e nelle altre app Nostr. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 nelle chat XMPP**: un messaggio a qualcuno la cui app parla OMEMO 2, come Kaidan, ora va con OMEMO 2 a quell’app e con OMEMO 0.3 alle sue altre app, come prima. La schermata XMPP mostra la chiave di questo dispositivo nei due modi, da confrontare con ciò che mostra ogni app. Vedi [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**Le chat nascoste possono avere i loro account Matrix, XMPP e Nostr**: sotto l’elenco di un posto di chat nascoste, Matrix, XMPP e Nostr aprono un account di quel solo posto, a parte quello dello spazio e tenuto cifrato con la chiave delle chat nascoste. Le sue chat si vedono solo tra le chat nascoste. Si collega mentre sono aperte, e anche da chiuse se Ricevere da chiuse è attivo, come le chat nascoste stesse: allora un messaggio dice solo «Nuovo messaggio», e una chiamata squilla senza nome e si risponde con il PIN. Vedi [Chat nascoste](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP e Nostr nei backup**: un backup ora contiene gli account Matrix, XMPP e Nostr di ogni spazio e delle sue chat nascoste. Dopo un ripristino, una chiave Nostr torna con le sue chat com’erano; un account XMPP prosegue come nuovo dispositivo dell’account, con i suoi contatti e le sue chat; un account Matrix viene lasciato andare su questo telefono, e lo spazio accede di nuovo come nuovo dispositivo; la sua chiave di sicurezza apre i messaggi di prima. Vedi [Backup](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**I messaggi vocali Matrix mostrano la loro forma d’onda, e le risposte Nostr possono essere foto**: un messaggio vocale inviato in una chat Matrix porta la sua forma d’onda, che Element disegna, e uno che arriva con la forma d’onda la mostra sotto Riproduci; in una chat Nostr, una foto, un file o un messaggio vocale inviato mentre un messaggio compare sopra il campo gli risponde. Vedi [Matrix](#matrix) e [Chat con altre app Nostr](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Chiamate di gruppo nei gruppi XMPP**: in un gruppo privato XMPP, avvia una chiamata vocale o video, rispondi a una che squilla, o unisciti a una in corso, insieme a persone che usano Dino. Vedi [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Una chiamata a un telefono lento squilla per intero**: chi chiama ora aspetta fino a un minuto e un quarto che l\'altro telefono dica che squilla, e poi 45 secondi da quel momento, così una chiamata arrivata in ritardo non squilla più per poi fermarsi subito; e il telefono chiamato legge una chiamata prima di tutto ciò che ha da inviare, e torna subito ad aspettare chiamate dopo un cambio di rete. Vedi [Chat tramite un relay](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**La web app e il computer raggiungono i server Matrix, XMPP e Nostr in HTTPS**: la politica della loro pagina ammetteva solo connessioni WebSocket, perciò lì non funzionavano l’accesso a Matrix, la scoperta del server XMPP e la condivisione di file, né i file e le ricerche di nomi su Nostr. Ora funzionano. Vedi [Matrix](#matrix), [XMPP](#xmpp) e [Chat con altre app Nostr](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Un messaggio inviato mentre una chat si apre la aspetta**, segnato Invio…, e parte appena la chat è aperta, senza dire che Erevos non può cifrare.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**Ciò che leggi mentre una chat si apre resta letto**: la schermata iniziale non lo conta più come nuovo.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Nessuna domanda di Samsung sulla sua condivisione**: su un telefono Samsung, Wi-Fi Aware e la rete Wi-Fi con i telefoni vicini restano spenti finché non li attivi. Vedi [Chattare con un telefono vicino](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**Il campo dell’SMS mantiene la sua larghezza su uno schermo piccolo**: Foto e Invia accanto sono pulsanti rotondi, come in una chat.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Invia risponde subito**: una breve vibrazione quando lo premi, il campo si svuota e il messaggio compare, segnato Invio…, così non parte mai due volte.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**Lo schermo non resta più spinto in alto** dopo che la tastiera si è chiusa dietro un pannello, una finestra di dialogo o un’altra app.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Importare una chat con le sue foto non blocca più Erevos**: lo schermo resta attivo mentre arrivano i file, dice quale parte è arrivata e **Annulla** la ferma. Una chat spostata nelle chat nascoste porta con sé le chat importate in essa. Vedi [Chat importate](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**Il tuo relay dimostra la sua chiave**: ogni connessione inizia con un controllo che solo il relay con quella chiave può superare, così nessuno nel mezzo può spacciarsi per lui. Dopo averla dimostrata, Erevos non lo raggiunge più senza il controllo. Per questo il tuo relay va aggiornato.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Trasparenza](#transparency), una nuova parte della guida: cosa conserva il server dietro Erevos e per quanto tempo, cosa non conserva, e chi altro vede qualcosa.',
  "**What's new**: this list, in Settings → General, by version.": '**Novità**: questo elenco, in Impostazioni → Generali, per versione.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Dietro il PIN di una chat non si vede niente**: nessun messaggio di una chat bloccata con un PIN viene mostrato prima che il suo PIN sia scritto, e con il vetro, uno sfondo o uno stile con una scena propria, la schermata del PIN è un vetro smerigliato fitto che non lascia vedere niente.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Una videochiamata di gruppo dalla parte alta del gruppo**: una videocamera blu accanto alla cornetta verde, come nella chat con un contatto.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Una coda del relay per ogni contatto**: ogni contatto scrive in una coda che conosce solo lui, così il relay non può capire che due contatti scrivono allo stesso telefono, ed eliminare o bloccare qualcuno cancella solo la sua. Il tuo relay deve essere aggiornato per questo.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**Le chat nascoste, più come le altre**: si chiudono dopo 30 secondi in background, non subito, e mai durante una chiamata o mentre scegli una foto o un file; mentre sono aperte, un messaggio fa il suo suono, e le anteprime dei link hanno lì un interruttore proprio. Vedi [Chat nascoste](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Chat nascoste che ricevono da chiuse**: un interruttore in cima a ogni posto, attivo nei posti nuovi, le fa ricevere come le tue altre chat: i loro contatti vedono subito che un messaggio è arrivato, una notifica dice solo «Nuovo messaggio», e una chiamata squilla senza nome. Vedi [Chat nascoste](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**Anche le chat nascoste aspettano e importano**: ciò che non può partire ora resta in attesa, segnato «In attesa», e parte da solo tramite il loro relay; «Invia più tardi» funziona lì come nelle tue altre chat; e una chat di Telegram, WhatsApp o Viber può essere importata in una chat nascosta, tenuta solo lì. Vedi [Chat nascoste](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**Le chat nascoste in un elenco come le tue chat**: si aprono su un elenco come quello della schermata iniziale, con l’ultima cosa detta e quanti non sono letti, e ogni posto ha in cima la sua Chat con me stesso. Vedi [Chat nascoste](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Di più nelle chat nascoste**: con Ricevere da chiuse, ciò che arriva loro tramite Nostr si legge anche mentre sono chiuse; e lì si può aggiungere un contatto da una foto del suo codice QR e dare una foto a un contatto nascosto. Vedi [Chat nascoste](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Chat nascoste senza relay**: come le tue altre chat, possono iniziare solo tramite Nostr: il loro link di contatto e il codice QR dicono dove leggono lì, e testi e reazioni vanno lì. Vedi [Chat nascoste](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Gruppi nelle chat nascoste**: sotto il loro elenco, Nuovo gruppo crea un gruppo con i loro contatti; compare tra le loro chat, passa solo dal loro relay e viene letto mentre sono chiuse se Ricevere da chiuse è attivo. Vedi [Chat nascoste](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Niente più riga sulla versione di prova**: la schermata iniziale non finisce più dicendo che è una versione di prova. La guida dice ancora esattamente cosa è protetto, e che niente è stato ancora verificato. Vedi [Cosa è protetto oggi](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**Il menu dei contatti nelle chat nascoste**: i loro Contatti hanno di nuovo un menu, solo con ciò che è loro: un file .vcf importato in esse, i loro contatti salvati come file .vcf e il codice QR di un contatto letto da una foto. Un ID Erevos scritto lì lo aggiunge alle chat nascoste. Vedi [Contatti](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**Il pulsante di chiamata normale per più contatti**: il tastierino arancione in cima alla chat di un contatto usa anche il numero del contatto a cui l’hai collegato (**Collega a uno dei miei contatti**), prima il cellulare.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Si possono importare le chat di Viber**: dal file HTML dell’app Android Backup Text for Viber, solo i testi.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Inizia senza relay, tramite Nostr**: **Inizia senza relay** in Nuova chat. Testi, sticker, reazioni, modifiche e i segni di consegna e lettura passano per Nostr, tramite Tor. Foto, messaggi vocali, file e chiamate richiedono ancora un relay o un telefono vicino.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**Il relay arriva da solo**: chi ha un relay che fa inviti manda una volta un invito a un contatto senza relay, dentro la chat, e l’altro telefono lo accetta da solo.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Avviso quando esce una nuova versione** (Android): una volta al giorno Erevos chiede al server di LPHL, poi mostra una riga Erevos fissata in alto e una notifica, solo per una versione firmata dal computer delle versioni. Si disattiva in Impostazioni → Generali → Aggiornamenti.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Blocca una chat con un PIN**: Dettagli → Blocca con un PIN, per chat e gruppi. Niente di quella chat compare nella ricerca, nei messaggi importanti o nelle importazioni. Nelle chat nascoste non chiede nessun PIN.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Una nuova cornetta** sui riquadri verdi: Telefono, e la chiamata in una chat.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Una nuova schermata Nuova chat**: «Come ti colleghi ora» in alto, tre grandi schede per un telefono senza relay (Ho un invito, Accedi con LPHL, Inizia senza relay), e la parte tecnica in «Per utenti esperti».',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr più stabile tramite Tor**: ogni relay Nostr ha il suo percorso in Tor, e dopo un errore prova una nuova uscita. Un messaggio di errore più chiaro nella schermata Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Quando la connessione al relay cade** mentre Erevos aspetta una risposta, Erevos se ne accorge e si ricollega, dove prima restava bloccato.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Invita via SMS** (Android): nella scheda di un contatto del telefono, per una persona, per 2 giorni. Il link apre una pagina che offre Erevos (l’APK per Android, la web app per iPhone o computer), poi apre l’invito. Il codice QR e Condividi l’invito restano come prima.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Correzioni all’invito via SMS**: funziona anche un link copiato come /i/#…, anche una web app più vecchia apre l’invito, e su iOS 26 dice che Condividi è dentro •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Un pulsante per le telefonate** nelle chat Erevos e nelle chat SMS.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Modifica un messaggio** che hai inviato, fino a un giorno dopo: per contatti, gruppi e dispositivi collegati, con Modificato accanto all’ora.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**Nostr dice cosa ha fatto**: «Inviato tramite Nostr», e nella schermata Nostr cosa ha fatto per ultimo ogni relay.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Pulsanti di chiamata colorati** in cima a una chat: video blu, voce verde.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Frecce per andare all’inizio e alla fine di una chat; i messaggi precedenti arrivano da soli mentre scorri.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'Le chat importate da Telegram e WhatsApp sembrano messaggi di Erevos: fumetti, giorni, foto, messaggi vocali, ricerca.',
  'Dogs instead of cats in the stickers.': 'Cani al posto dei gatti negli sticker.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Screenshot: un interruttore in Impostazioni → Privacy e sicurezza.',
  'Hidden chats from New chat: hold it for a second.': 'Chat nascoste da Nuova chat: tienila premuta per un secondo.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Riquadri colorati nella schermata principale: Telefono verde, Contatti viola, il lucchetto arancione.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Chat con me stesso**, sempre in cima, e **Ricordamelo**, la campanella arancione.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Media, link e file** nei Dettagli di una chat, con un calendario e Vai a un giorno.',
  'Import a chat from inside the chat: Details → Imported chats.': 'Importa una chat da dentro la chat stessa: Dettagli → Chat importate.',
  'A closed space can say that a message came while another space is open.': 'Uno spazio chiuso può dire che è arrivato un messaggio mentre è aperto un altro spazio.',
  'The message menu says when a message went or came through Nostr.': 'Il menu del messaggio dice quando un messaggio è partito o arrivato tramite Nostr.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Sostieni Erevos**: Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Chi fa Erevos e perché, in Informazioni su Erevos; la guida spiega ovunque il perché.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Impostazioni in 8 gruppi**, con una ricerca: Generali, Aspetto, Notifiche, Privacy e sicurezza, Relay e reti, Telefono e SMS, Dati e dispositivi, Per i test. Il ⋯ della schermata principale tiene solo le schermate, e per ultime le Impostazioni.',
  // 3.1.1
  'Check for updates says what stopped an update.': 'Cerca aggiornamenti dice cosa ha bloccato un aggiornamento.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    'Invita qualcuno non parte più da un token condiviso; prima ti chiede di accedere al relay.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'Il token condiviso del relay diventa da solo un token tutto del telefono (serve il relay aggiornato).',
  'A relay that refuses through Tor says why.': 'Un relay che rifiuta tramite Tor dice perché.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Meno batteria in background: il relay, Tor e le radio per i telefoni vicini.',
  'Erevos no longer closes when you make a sticker from a photo.': 'Erevos non si chiude più quando crei uno sticker da una foto.',
  'Hidden chats’ notices are right.': 'Le notifiche delle chat nascoste sono corrette.',
  'Hidden chats by holding New chat.': 'Chat nascoste tenendo premuto Nuova chat.',
  'A search for contacts on the Phone.': 'Una ricerca dei contatti nel Telefono.',
  'New chat shows first how to add a contact.': 'Nuova chat mostra per prima cosa come aggiungere un contatto.',
  'A call shows over the screen saver, and the screen wakes.': 'Una chiamata appare sopra il salvaschermo, e lo schermo si riaccende.',
  'Erevos in other apps’ Share.': 'Erevos in Condividi delle altre app.',
  'A sound for every new message, also while Erevos shows.': 'Un suono per ogni nuovo messaggio, anche mentre Erevos è aperto.',
  'The SMS settings say right what holding does.': 'Le impostazioni SMS dicono bene cosa succede tenendo premuto.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Ogni icona apre ciò che indica: Erevos, SMS, Telefono, Contatti, il widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Messaggi tramite Tor in modo predefinito**: Messaggi, Tutto o Niente.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**I testi tramite Nostr**: tre relay pubblici, tramite Tor, con il tuo relay come riserva dopo 5 minuti.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Un solo invito per tutto: il relay e il contatto insieme.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Regole antispam per mittenti e numeri esteri, con il motivo.',
  '480 stickers in 20 sets.': '480 sticker in 20 set.',
  'Lighter chats on older phones; QR codes at once.': 'Chat più leggere sui telefoni più vecchi; codici QR subito.',
  'Copy code for one-time codes in SMS.': 'Copia codice per i codici monouso negli SMS.',
  'Locked, Erevos keeps receiving.': 'Anche bloccato, Erevos continua a ricevere.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Contatti più veloci; la notifica delle chat nascoste conta solo i messaggi.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'Il relay prova ogni indirizzo: push, altri relay, l’accesso con LPHL.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Scorrere sulle schede cambia solo la scheda.',
  'The icons fill the launcher’s shape.': 'Le icone riempiono la forma del launcher.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Icone colorate (Erevos rosso, Telefono verde, SMS blu, Contatti viola) e una nuova icona SMS.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Un colore per ogni icona, e l’ordine dei pulsanti del widget.',
  'Swipe to go back, and between tabs.': 'Scorri per tornare indietro, e tra le schede.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Un aggiornamento della WebView non chiude più Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Eliminare o bloccare un contatto ti dà una nuova coda sul relay.',
  'A new contact can take the name of a contact on the phone.': 'Un nuovo contatto può prendere il nome di un contatto del telefono.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Accesso al relay con LPHL**, e **inviti al relay**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Permessi nella web app, e altri su Android; la notifica della web app dice quanti messaggi sono arrivati.',
  'Hidden chats can ring calls while they are closed.': 'Le chat nascoste possono far squillare le chiamate mentre sono chiuse.',
  'New keys every month in chats, every week in groups.': 'Chiavi nuove ogni mese nelle chat, ogni settimana nei gruppi.',
  'Linked devices work with the phone off.': 'I dispositivi collegati funzionano con il telefono spento.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Una nuova schermata della chat; codici QR da una foto; il Telefono per schermi piccoli.',
  'Add as contact inside a group.': 'Aggiungi come contatto dentro un gruppo.',
  'Stickers in sets, moving, and your own.': 'Sticker in set, animati, e i tuoi.',
  'SMS inside the Erevos chat.': 'Gli SMS dentro la chat di Erevos.',
  'Android updates need the release computer’s signature.': 'Gli aggiornamenti Android richiedono la firma del computer delle versioni.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Una versione per F-Droid; il serbo-croato; nuovi numeri di versione.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Molto per la sicurezza: Argon2id, messaggi cifrati anche per il relay, un token per ogni telefono, nessun link avvia una chiamata.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'Le importazioni da Telegram e WhatsApp portano foto, video, messaggi vocali e file.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Un telefono senza relay comunica tramite un posto sul relay di un contatto.',
  // 0.1.14
  'Back to my chats, for hidden chats.': 'Riporta nelle mie chat, per le chat nascoste.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'Erevos riceve e squilla anche dopo che lo togli dalle app recenti.',
  // 0.1.12
  'Hidden chats can say a message came.': 'Le chat nascoste possono dire che è arrivato un messaggio.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Correzioni: menu, codici QR da una foto, Bluetooth su Android 17, elenchi lunghi.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'Il Telefono senza password, se lo permetti; un widget per la schermata principale; un filtro SMS ed Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'I link aspettano la password; icone di Telefono e Contatti; l’ID Erevos su un contatto.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 nuove funzioni: 5 nuove lingue, dispositivi collegati, gruppi pubblici, risposte, reazioni, sondaggi, invio più tardi, Erevos come app per telefono e contatti, bridge Tor, l’impronta, Windows e altro.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'Notifiche SMS in background.',
  'The web app comes out with every release.': 'La web app esce con ogni versione.',
  'Greek in the whole app.': 'Il greco in tutta l’app.',
  'Web Push in the web app.': 'Web Push nella web app.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'La prima versione Android firmata: chat cifrate, chiamate, gruppi, chat nascoste, backup, importazioni, e telefoni vicini senza internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Due nuovi set di adesivi con 24 stati d'animo**: **Tux**, il pinguino di Linux così com'è disegnato, e **Aikido**, un aikidoka in keikogi e ampio hakama, che si inchina anche, siede in seiza e fa una capriola.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Un nuovo set di adesivi, Takis**: una caricatura in abito scuro e cravatta viola a pois, in 24 stati d'animo che si muovono.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Foto, file e messaggi vocali senza relay**: quando non c’è un relay tra te e il tuo contatto e lui legge su Nostr, un messaggio vocale passa da Nostr come un testo, una foto fino a 3 MB in pezzi, e una foto più grande, un video o un altro file, fino a 20 MB, verso un server di file cifrato (Blossom), tutto tramite Tor. Vedi [Tramite Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Più batteria risparmiata in secondo piano, se lo scegli**: in Impostazioni → Notifiche → In background, Solo lo spreco resta il predefinito; E i telefoni vicini spegne anche le radio per i telefoni vicini finché Erevos è in secondo piano; E il sonno lascia dormire anche il telefono, così Erevos guarda il tuo relay circa una volta al minuto e un messaggio o una chiamata può arrivare con uno o due minuti di ritardo. Solo Android. Vedi [Chat tramite un relay](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Un contatto eliminato non torna più da una vecchia richiesta**: in un gruppo, un membro di cui avevi chiesto il link di contatto, o che aveva chiesto il tuo, e che poi eliminavi come contatto prima che Erevos guardasse di nuovo il relay, poteva essere aggiunto di nuovo da quella vecchia richiesta. Ora eliminarlo la lascia subito. Vedi [Chat di gruppo](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Ogni messaggio dice da che parte è passato**: tieni premuto un messaggio e il suo menu dice se è andato o arrivato tramite il relay, tramite Nostr, da un telefono vicino o tramite LoRa. I messaggi di prima non dicono nulla. Vedi [Tramite Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**Il filtro dello spam legge le parole come appaiono**: un SMS truffa che cambia una lettera con una simile di un altro alfabeto, o nasconde in una parola un segno che non si vede, non lo inganna più. Vedi [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Media, link e file anche nei gruppi**: nei dettagli di un gruppo, un elenco delle sue foto, video, messaggi vocali, musica, file e link, ogni tipo a parte sotto i suoi mesi, con un calendario, come nella chat di un contatto. Un tocco apre o riproduce; tenuto premuto, ognuno va al suo messaggio. Vedi [Chat di gruppo](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Un riavvio del relay non porta più una notifica falsa**: dopo il riavvio del tuo relay, una chat nascosta o uno spazio chiuso diceva di nuovo Nuovo messaggio per messaggi di cui aveva già avvisato. Il tuo relay deve essere aggiornato per questo. Vedi [Chat nascoste](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Backup sul tuo server tramite Tor**: su Android, i backup automatici inviati al tuo server ora seguono la scelta dello spazio in Impostazioni → Relay e reti → Tor, come Matrix, così con Tor il server non vede più dove sei. Anche su un server dice quando passano per Tor. Vedi [Backup](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Ripristina un backup direttamente dal tuo server**: Ripristina da un server, in Backup, mostra i backup sul tuo server, i più recenti per primi, e apre quello che scegli con la sua password, senza scaricarlo a mano, anche su un telefono nuovo. Vedi [Backup](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Backup sul tuo server anche dal computer e dalla web app**: nell'app per computer i backup automatici vanno al tuo server WebDAV come su Android; nella web app, Invia un backup ora ne invia uno lì, con un server che fa entrare la web app. Entrambe possono ripristinare da lì. Non tramite Tor. Vedi [Backup](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Verifica un contatto di persona con i codici QR**: in Codice di sicurezza, nei dettagli di una chat, ogni telefono mostra un codice; fotografa il codice sull’altro telefono, e lui il tuo. Quando corrisponde, il contatto viene segnato Verificato di persona. Non viene inviato nulla. Vedi [Chat tramite un relay](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Fino a tre relay di casa**: in Impostazioni → Relay e reti → Relay di casa, Aggiungi un altro relay di casa dà a uno spazio fino a due in più, ognuno con la sua coda. Il tuo link di contatto e i tuoi messaggi li nominano in ordine, e i contatti provano ciascuno finché i precedenti non si raggiungono. Vedi [Relay di casa](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Presenta due dei tuoi contatti**: nei dettagli della chat di un contatto, Presenta a un contatto chiede a lui e a un altro dei tuoi contatti, a ciascuno nella tua chat con lui. Diventano contatti solo se entrambi dicono di sì, e nessuno sa se l’altro ha detto di no. Vedi [Chat tramite un relay](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Bluetooth che non si può seguire**: il numero casuale che il tuo telefono trasmette via Bluetooth perché i telefoni vicini lo trovino cambiava solo al riavvio di Erevos; ora cambia ogni nove-dodici minuti, così chi ascolta non può seguire il tuo telefono da un posto all’altro con esso. I telefoni con un Erevos più vecchio trovano ancora il tuo. Vedi [Chat con un telefono vicino](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**Le chat nascoste si vedono subito**: appena il PIN le apre, le loro chat e i loro contatti si vedono subito, per leggerli, mentre termina ciò che ricevevano in background; prima, ciò poteva trattenerle a lungo, perché può passare tramite Tor. Vedi [Chat nascoste](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**La password dei tuoi backup in pezzi presso amici**: in Impostazioni → Dati e dispositivi → Pezzi del backup, danne dei pezzi a 3-5 contatti; 2 o 3 qualsiasi la restituiscono, uno solo non mostra nulla. Ognuno viaggia dentro la crittografia della tua chat con loro e solo il loro Erevos lo conserva; il tuo telefono non ne tiene nessuno. Vedi [Pezzi del backup presso amici](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Pulsante di panico**: in Impostazioni → Privacy e sicurezza → Pulsante di panico, cancella con un tocco tutto ciò che Erevos tiene qui, su Android e nell’app web. Su Android può farlo anche un’app di panico come Ripple, ma solo quella a cui dici di sì, controllata dalla sua firma. Vedi [Pulsante di panico](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**Erevos a un telefono vicino, senza internet**: in Impostazioni → Generali → Dai Erevos a un telefono vicino, questo telefono serve il suo Erevos sulla stessa Wi-Fi o sul suo hotspot per dieci minuti, con un codice QR. Un telefono senza Erevos lo scarica nel browser; uno con un Erevos più vecchio lo prende in Aggiornamenti → Da un telefono vicino, che lo installa solo se è Erevos, firmato come quello. Vedi [Erevos a un telefono vicino](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Chat nascoste con i telefoni vicini**: mentre le chat nascoste sono aperte, o ricevono da chiuse, raggiungono il telefono di un contatto vicino via Bluetooth, Wi-Fi Aware, Wi-Fi Direct o sulla stessa rete Wi-Fi, senza internet, come le tue altre chat. Lo spazio non sa mai che un contatto nascosto è vicino, e niente nell’aria distingue i loro messaggi da quelli dello spazio; altri telefoni non li portano mai, e non passano mai via LoRa né via SMS. Vedi [Chat nascoste](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**La stessa rete Wi-Fi su Sailfish OS**: Erevos su Sailfish OS trova telefoni e computer con Erevos sulla stessa rete Wi-Fi o sull’hotspot di un telefono e parla con loro senza internet, come su un computer. Vedi [Su Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**I download si fermano a 100 MB**: un file, un backup da un server o qualsiasi altro download viene letto man mano che arriva e fermato appena supera i 100 MB, o meno dove i file della rete sono più piccoli, come 20 MB per i file di Nostr, così un file server indicato da un contatto non può più riempire la memoria del telefono con una risposta senza fine. Un backup su un server torna fino a 100 MB; uno più grande scaricalo e aprilo con Ripristina un backup. Vedi [Backup](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Foto del profilo su Matrix e XMPP**: i contatti e le stanze Matrix mostrano la loro foto nell’elenco delle chat, e puoi mettere la tua nelle schermate Matrix e XMPP (Scegli una foto). Le foto non sono cifrate su nessuna delle due reti: il server le vede. Vedi [Matrix](#matrix) e [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Gestire un gruppo XMPP**: gli admin di un gruppo ne impostano l’oggetto e rimuovono o escludono persone, il proprietario lo rinomina e nomina admin, e in un canale l’admin vede chi c’è dentro e può farlo uscire. Vedi [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Verificare un dispositivo Matrix con codice QR**: quando entrambi accettano una verifica, Erevos mostra un codice da far fotografare a Element (o a un altro Erevos), o fotografa il loro, come fa Element; il confronto delle emoji resta a un tocco. Vedi [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Accedere a Matrix con il single sign-on** (Android): quando il tuo server Matrix fa accedere le persone sulla propria pagina, come matrix.org, «Accedi con accesso unico (SSO)» la apre nel browser e torna a Erevos. Vedi [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Uno spazio chiuso avvisa dei messaggi XMPP**: su Android, «Avvisa dei nuovi messaggi» in «Mentre questo spazio è chiuso», nella schermata di XMPP, lascia che uno spazio chiuso dica «New message» quando arriva qualcosa su XMPP mentre è aperto un altro spazio, mai cosa, da chi o in quale chat. Spento finché non lo scegli. Serve un relay aggiornato per questo e un server XMPP che mandi avvisi alle app inattive; il server XMPP conosce allora il nome del relay, e il relay quando arrivano messaggi. Vedi [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Collegare un computer è più chiaro**: su un computer, Impostazioni → Dati e dispositivi → Dispositivi collegati ora comincia con «Collega al mio telefono», con il relay di LPHL già inserito e «Accedi con LPHL» sotto il token, così non serve copiare nessun token dal telefono; e dice che il codice QR compare quando si tocca «Collega al mio telefono». Vedi [Dispositivi collegati](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Cancellami da ovunque**: Impostazioni → Privacy e sicurezza → Cancellami da ovunque cancella ciò che i server conservano per lo spazio aperto (le sue code sui relay con i messaggi dentro, ciò che un relay tiene per inviarlo dopo, i file che vi aspettano, gli inviti che nessuno ha usato), chiede via Tor ai relay Nostr di dimenticare le chiavi su cui leggono le tue chat, e ferma lo spazio finché non tocchi Riavvia. Il tuo telefono conserva tutto. Puoi anche uscire da Matrix e XMPP e cancellare l'account Nostr creato qui. Vedi [Cancellami da ovunque](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Ogni coda del relay in un elenco**: le code che uno spazio tiene sui relay sono riunite in un solo posto, e i controlli falliscono se si crea un nuovo tipo di coda senza aggiungerlo lì, così Cancellami da ovunque non ne lascia nessuna.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP e Nostr su un computer collegato**: collegando un computer si possono portare anche gli account Matrix e XMPP di questo spazio e la chiave delle sue chat Nostr, ciascuno con l’accesso eseguito lì come nuovo dispositivo a sé; per un computer già collegato, tocca «Invia gli account» sotto di esso sul telefono. Un server Matrix di rado lascia che il telefono faccia accedere il computer: il computer chiede allora una volta la password di Matrix, e le chiavi dell’account arrivano dal telefono, quindi non servono né la chiave di sicurezza né la verifica con le emoji. Vedi [Dispositivi collegati](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Solo gli SMS**: con Erevos bloccato, l’icona SMS, il pulsante SMS del widget e la notifica di un nuovo SMS chiedono la password e poi aprono solo gli SMS. Tutto il resto, compreso il lucchetto arancione **Sblocca tutto**, la chiede di nuovo e poi apre tutto Erevos. Vedi [Blocco con password](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**Le chat Nostr con una chiave portata da un’altra app tornano a ricevere i loro messaggi**: Erevos legge dove quell’app ha detto che arrivano i tuoi messaggi, come fa quell’app, invece dei suoi tre relay, recupera i messaggi tenuti lì e nelle liste precedenti della chiave, e rilegge un relay quando smette di inviare. Prima, una chiave così poteva mostrare le sue chat senza messaggi passati e non riceverne di nuovi. Vedi [Chat con altre app Nostr](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**I backup tengono ciò che serve alle chat chiuse**: un backup ora tiene anche ciò che permette alle chat nascoste di far squillare una chiamata e di avvisare che è arrivato un messaggio mentre sono chiuse, e a uno spazio chiuso di avvisare che ne è arrivato uno. Così, dopo un ripristino, anche su un altro telefono, **Fai squillare le chiamate quando sono chiuse**, **Avvisa quando arriva un messaggio** e **Anche mentre è aperto un altro spazio** continuano come prima. Vedi [Backup](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Aprire un altro spazio dalla ricerca**: scrivi la password di un altro spazio in **Cerca nelle chat** nella schermata principale e premi Invio: lo spazio aperto si chiude, senza che ne resti nulla, e si apre l’altro, come con **Blocca ora** e la sua password. Ci mette lo stesso tempo qualunque cosa scrivi, e una password sbagliata, o quella dello spazio aperto, è solo una ricerca. Vedi [Seconda password](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Un punto per i non letti altrove, se lo vuoi**: le chat nascoste con **Ricevere da chiuse** possono mostrare un piccolo punto sulla lente di **Cerca nelle chat** finché hanno un messaggio non letto (il loro interruttore **Punto per i non letti**), e uno spazio che avvisa che è arrivato un messaggio mentre ne è aperto un altro può mostrarne uno sul lucchetto sopra le chat degli altri spazi (**Punto negli altri spazi**). Mai quanti, né dove; spento a meno che non lo accendi. Vedi [Chat nascoste](#hidden).",
};
